`timescale 1ns/1ps

// Seeded source stalls, FIFO occupancy, phase drift, mute and reset epochs.
// Expected pin frames are generated by Python, not by the RTL serializer.
module hdmi_audio_cdc_random_tb;
    logic source_clk = 0, audio_clk = 0;
    logic source_reset = 1, audio_reset = 1;
    logic signed [15:0] pcm_sample = 0;
    logic pcm_valid = 0, accept_samples = 0, fifo_flush = 1;
    logic sample_ready, stream_enable = 0, mute = 0;
    logic i2s_bclk, i2s_lrclk, i2s_data, primed;
    logic [15:0] fifo_occupancy;
    logic [31:0] sample_count, fifo_underruns, fifo_overruns;
    logic [15:0] samples [0:255];
    logic [63:0] expected_frames [0:255];
    integer cycles = 0, checked = 0, high_water = 0;
    always #10 source_clk = !source_clk;
    // Deliberately independent oscillator phase/frequency in simulation.
    always #10.007 audio_clk = !audio_clk;
    always @(posedge source_clk) begin
        cycles = cycles + 1;
        if (int'(fifo_occupancy) > high_water)
            high_water = int'(fifo_occupancy);
        if (cycles > 500000) $fatal(1, "CDC randomized timeout");
    end
    hdmi_audio_transport dut (.*);

    task automatic push(input integer index);
        @(negedge source_clk);
        while (!sample_ready) @(negedge source_clk);
        pcm_sample = samples[index];
        pcm_valid = 1;
        @(negedge source_clk);
        pcm_valid = 0;
    endtask

    initial begin
        $readmemh("build/sim/phase6d_random_pcm.hex", samples);
        $readmemh("build/sim/phase6d_random_i2s.hex", expected_frames);
        for (integer epoch = 0; epoch < 4; epoch++) begin
            stream_enable = 0;
            accept_samples = 0;
            fifo_flush = 1;
            source_reset = 1;
            audio_reset = 1;
            repeat (5 + int'(samples[epoch][3:0])) @(negedge source_clk);
            source_reset = 0;
            audio_reset = 0;
            repeat (5) @(negedge source_clk);
            fifo_flush = 0;
            accept_samples = 1;
            for (integer i = 0; i < 4; i++) push(epoch*64+i);
            repeat (5) @(negedge source_clk);
            if (!primed) $fatal(1, "CDC prime failed");
            mute = samples[epoch*64][4:0] == 13;
            stream_enable = 1;
            fork
                begin
                    for (integer i = 4; i < 64; i++) begin
                        repeat (int'(samples[epoch*64+i][9:0])) @(negedge source_clk);
                        push(epoch*64+i);
                    end
                end
                begin
                    for (integer i = 0; i < 64; i++) begin
                        @(posedge dut.serializer.frame_event);
                        for (integer bit_index = 0; bit_index < 64; bit_index++) begin
                            @(posedge i2s_bclk);
                            if (i2s_lrclk !== (bit_index >= 32) ||
                                i2s_data !== expected_frames[epoch*64+i][63-bit_index])
                                $fatal(1, "CDC model mismatch epoch=%0d sample=%0d bit=%0d", epoch, i, bit_index);
                        end
                        checked++;
                        if (i < 63) mute = samples[epoch*64+i+1][4:0] == 13;
                    end
                end
            join
            stream_enable = 0;
            repeat (5) @(negedge source_clk);
            if (sample_count != 64 || fifo_occupancy != 0 ||
                fifo_underruns != 0 || fifo_overruns != 0)
                $fatal(1, "CDC accounting samples=%0d occupancy=%0d under=%0d over=%0d",
                    sample_count, fifo_occupancy, fifo_underruns, fifo_overruns);
        end
        $display("Phase 6D CDC randomized passed: seed=0x6d480001 cycles=%0d samples=%0d high_water=%0d reset_epochs=4 mismatches=0", cycles, checked, high_water);
        $finish;
    end
endmodule
